import math

import adsk.core
import adsk.fusion


def _box(tbm, cx, cy, cz, lx, ly, lz):
    """An axis-aligned box in the GLOBAL X/Y/Z frame. mm in, cm internally."""
    obb = adsk.core.OrientedBoundingBox3D.create(
        adsk.core.Point3D.create(cx / 10.0, cy / 10.0, cz / 10.0),
        adsk.core.Vector3D.create(1.0, 0.0, 0.0),
        adsk.core.Vector3D.create(0.0, 1.0, 0.0),
        lx / 10.0, ly / 10.0, lz / 10.0)
    return tbm.createBox(obb)


def _cyl(tbm, x, y, z0, z1, r):
    """A cylinder on an axis PARALLEL TO Z, from z0 to z1. mm in, cm internally."""
    return tbm.createCylinderOrCone(
        adsk.core.Point3D.create(x / 10.0, y / 10.0, z0 / 10.0), r / 10.0,
        adsk.core.Point3D.create(x / 10.0, y / 10.0, z1 / 10.0), r / 10.0)


def _quadrant_axes(quadrant):
    """u = radial direction, v = tangential direction, at 90 deg * quadrant about Z."""
    a = math.radians(quadrant * 90.0)
    u = adsk.core.Vector3D.create(math.cos(a), math.sin(a), 0.0)
    v = adsk.core.Vector3D.create(-math.sin(a), math.cos(a), 0.0)
    return u, v


def _quadrant_box(tbm, quadrant, r_lo, r_hi, y_lo, y_hi, z_lo, z_hi):
    """A box whose length runs radially and width tangentially, at a given quadrant
    (0/1/2/3 = 0/90/180/270 deg about the rocket Z axis) -- ports
    `cad/canard_bay.fs`'s `quadrantCuboid`. mm in, cm internally.
    """
    u, v = _quadrant_axes(quadrant)
    r_lo, r_hi = min(r_lo, r_hi), max(r_lo, r_hi)
    y_lo, y_hi = min(y_lo, y_hi), max(y_lo, y_hi)
    z_lo, z_hi = min(z_lo, z_hi), max(z_lo, z_hi)
    rc, yc, zc = (r_lo + r_hi) / 2.0, (y_lo + y_hi) / 2.0, (z_lo + z_hi) / 2.0
    center = adsk.core.Point3D.create(
        (u.x * rc + v.x * yc) / 10.0, (u.y * rc + v.y * yc) / 10.0, zc / 10.0)
    obb = adsk.core.OrientedBoundingBox3D.create(
        center, u, v, (r_hi - r_lo) / 10.0, (y_hi - y_lo) / 10.0, (z_hi - z_lo) / 10.0)
    return tbm.createBox(obb)


def _radial_cyl(tbm, quadrant, across, z, r0, r1, r):
    """A cylinder on a RADIAL axis at the given quadrant, spanning radius r0 -> r1, offset
    `across` tangentially -- ports `cad/canard_bay.fs`'s `radialCylinder`. mm in, cm
    internally.
    """
    u, v = _quadrant_axes(quadrant)
    bx, by = v.x * across, v.y * across
    p0 = adsk.core.Point3D.create((bx + u.x * r0) / 10.0, (by + u.y * r0) / 10.0, z / 10.0)
    p1 = adsk.core.Point3D.create((bx + u.x * r1) / 10.0, (by + u.y * r1) / 10.0, z / 10.0)
    return tbm.createCylinderOrCone(p0, r / 10.0, p1, r / 10.0)


def _cut(tbm, target, tool, what):
    """Boolean subtract. NOTE: booleanOperation returns a BOOL and mutates `target` in
    place -- never assign its result back, per make_sled_fusion.py's own warning.
    """
    if not tbm.booleanOperation(target, tool, adsk.fusion.BooleanTypes.DifferenceBooleanType):
        raise ValueError("cut %s did not take" % what)


def _union(tbm, target, tool, what):
    if not tbm.booleanOperation(target, tool, adsk.fusion.BooleanTypes.UnionBooleanType):
        raise ValueError("union %s did not take" % what)


def _get_or_create_component(root, name):
    """Find an existing occurrence by component name, else create a new empty one.

    Returns (occurrence, already_has_bodies). A caller that finds `already_has_bodies`
    True should verify rather than rebuild -- the same idempotency rule
    `make_sled_fusion.py` uses.
    """
    for o in root.occurrences:
        if o.component.name == name:
            return o, o.component.bRepBodies.count > 0
    occ = root.occurrences.addNewComponent(adsk.core.Matrix3D.create())
    occ.component.name = name
    return occ, False


def _inject(comp, made):
    """Inject a list of (name, body) temporary BRep bodies through one BaseFeature.

    Mandatory for a parametric document: a temp body only "takes" via
    `BRepBodies.add(body, baseFeature)`, per make_sled_fusion.py's own header.

    RENAMING HAPPENS AFTER `finishEdit()`, VIA A FRESH QUERY -- not on the object
    `BRepBodies.add()` itself returns, and not inside the startEdit/finishEdit
    transaction. Confirmed by direct test: for a body sourced from Fusion's parametric
    Sketch/Extrude API (copied out via `TemporaryBRepManager.copy()`, the technique the
    canard panels and aft fins both use for their swept-trapezoid profile), setting
    `.name` on the object `.add()` returns reads back correctly on THAT SAME object but
    does not persist to the body at all -- a fresh `comp.bRepBodies` query even in the
    same script run still shows Fusion's own default name ("Body1"). Renaming a FRESH
    query result AFTER `finishEdit()` does persist, for both extrude-sourced and
    primitive-sourced (box/cylinder/boolean) bodies alike, so every generator does it
    this way now rather than the two of them disagreeing on which pattern is safe. This
    is a DIFFERENT failure mode from `_get_or_create_component`'s own idempotency note
    above (same-transaction rename into an ALREADY-POPULATED component) -- that one is
    about a LATER, separate script run; this one bites inside the very run that created
    the body.
    """
    before = comp.bRepBodies.count
    bf = comp.features.baseFeatures.add()
    bf.startEdit()
    for (name, body) in made:
        comp.bRepBodies.add(body, bf)
    bf.finishEdit()
    for i, (name, _body) in enumerate(made):
        comp.bRepBodies.item(before + i).name = name


def _verify_volume(comp, want, tol, loose=(), loose_tol=None):
    """Compare each named body's volume (mm3) against an analytic expectation.

    `loose` names bodies (radial holes through curved walls, or a part whose analytic
    figure is itself an estimate) that get `loose_tol` instead of `tol` -- measured, not
    guessed, the same discipline make_sled_fusion.py's PORT_VOLUME_TOLERANCE_PER_PORT uses.
    Returns a list of violation strings (empty if everything is within tolerance).
    """
    acc = adsk.fusion.CalculationAccuracy.VeryHighCalculationAccuracy
    got = {}
    for b in comp.bRepBodies:
        got[b.name] = b.getPhysicalProperties(acc).volume * 1e3
    bad = []
    for name, wv in want.items():
        if name not in got:
            bad.append("%s is missing" % name)
            continue
        t = loose_tol if (name in loose and loose_tol is not None) else tol
        d = got[name] - wv
        print("  %-28s %14.4f mm3  want %14.4f  delta %+9.4f  (tol %.3f)"
              % (name, got[name], wv, d, t))
        if abs(d) > t:
            bad.append("%s is %+.4f mm3 out" % (name, d))
    return bad


def _verify_cyl_faces(body, radius, axis_is_radial):
    """Count cylindrical faces at `radius` (mm) and read back their clocking, in degrees
    mod 180. `axis_is_radial` True keeps only faces whose axis has no Z component (a
    radial hole); False keeps only faces whose axis IS parallel to Z (an axial hole).
    Exact where a volume check on a radial hole through a curved wall is not -- see
    make_sled_fusion.py's header for why that matters.
    """
    found = []
    for f in body.faces:
        g = f.geometry
        if not g.objectType.endswith("Cylinder"):
            continue
        if abs(g.radius * 10.0 - radius) > 1e-6:
            continue
        ax = g.axis
        is_radial = abs(ax.z) < 1e-9
        if is_radial != axis_is_radial:
            continue
        found.append(math.degrees(math.atan2(ax.y, ax.x)) % 180.0)
    return sorted(found)


VOLUME_TOLERANCE_MM3 = 0.01
SLOT_TOLERANCE_MM3 = 2.0
OVER_MM = 1.0
N_FINS = 4
AFT_FIN_CLOCK_DEG = 45.0

DISC_R_MM = 37.400000000000006
DISC_T_MM = 4.8
DISC_Z0_MM = 579.62
DISC_VOLUME_MM3 = 20201.219877560467
HOLES = [('drogue charge feed-through', 22.59775238156248, 0.0, 4.0), ('U-bolt leg A', 0.0, 12.5, 10.5), ('U-bolt leg B', 0.0, -12.5, 10.5)]

TUBE_OR_MM = 28.55
TUBE_IR_MM = 27.25
TUBE_Z0_MM = 584.42
TUBE_Z1_MM = 920.5
TUBE_VOLUME_MM3 = 76589.65133719901

RINGS = [
    {'name': 'CenteringRing0', 'body': 'forward centering ring', 'ro': 37.400000000000006, 'ri': 28.55, 't': 3.2, 'z0': 764.4399999999998, 'slots': 0, 'slot_width': 3.2, 'slot_r_lo': 28.55, 'volume': 5867.565165480275, 'slot_volume': 0.0},
    {'name': 'CenteringRing1', 'body': 'aft centering ring (slotted)', 'ro': 37.400000000000006, 'ri': 28.55, 't': 3.2, 'z0': 902.3, 'slots': 4, 'slot_width': 3.2, 'slot_r_lo': 28.55, 'volume': 5505.069165480275, 'slot_volume': 90.62400000000007}
]

MOTOR_R_MM = 27.0
MOTOR_Z0_MM = 595.5
MOTOR_Z1_MM = 920.5
MOTOR_VOLUME_MM3 = 744321.8394517617

TAB_Z0_MM = 775.6399999999998
TAB_Z1_MM = 914.4999999999998


def _rotate_z(tbm, body, angle_deg):
    m = adsk.core.Matrix3D.create()
    m.setToRotation(math.radians(angle_deg), adsk.core.Vector3D.create(0.0, 0.0, 1.0),
                    adsk.core.Point3D.create(0.0, 0.0, 0.0))
    if not tbm.transform(body, m):
        raise ValueError("rotation to %.1f deg did not take" % angle_deg)
    return body


def _annulus(tbm, ro, ri, z0, z1):
    outer = _cyl(tbm, 0.0, 0.0, z0, z1, ro)
    _cut(tbm, outer, _cyl(tbm, 0.0, 0.0, z0 - OVER_MM, z1 + OVER_MM, ri), "bore")
    return outer


def _pair_interference(tbm, a, b):
    """mm3 of overlap between two bodies. Intersection, measured, not eyeballed -- the
    same technique correction 40 used to find 21 clashing pairs the eye had passed."""
    ca = tbm.copy(a)
    cb = tbm.copy(b)
    if not tbm.booleanOperation(ca, cb, adsk.fusion.BooleanTypes.IntersectionBooleanType):
        return 0.0
    return ca.volume * 1e3 if ca is not None else 0.0


def _bodies_named(root, comp_name):
    for o in root.occurrences:
        if o.component.name == comp_name:
            return list(o.bRepBodies)
    return []


def run(_context: str):
    app = adsk.core.Application.get()
    des = adsk.fusion.Design.cast(app.activeProduct)
    root = des.rootComponent
    tbm = adsk.fusion.TemporaryBRepManager.get()
    bad = []

    # ---- the forward bulkhead: solid disc, then the holes ------------------------------
    occ, has_bodies = _get_or_create_component(root, "BoosterForwardBulkhead")
    if not has_bodies:
        disc = _cyl(tbm, 0.0, 0.0, DISC_Z0_MM, DISC_Z0_MM + DISC_T_MM, DISC_R_MM)
        for (name, hx, hy, hd) in HOLES:
            _cut(tbm, disc,
                 _cyl(tbm, hx, hy, DISC_Z0_MM - OVER_MM, DISC_Z0_MM + DISC_T_MM + OVER_MM,
                      hd / 2.0), name)
        _inject(occ.component, [("booster forward bulkhead", disc)])
        print("BoosterForwardBulkhead: built with %d holes" % len(HOLES))
    else:
        print("BoosterForwardBulkhead: already has bodies, verifying only")
    bad += _verify_volume(occ.component,
                          {"booster forward bulkhead": DISC_VOLUME_MM3},
                          VOLUME_TOLERANCE_MM3)

    # A volume check cannot tell a hole that was cut from one cut somewhere else, so read
    # the cylindrical faces back and confirm one axial bore exists at each hole's radius.
    disc_body = occ.component.bRepBodies.item(0)
    for (name, hx, hy, hd) in HOLES:
        if not _verify_cyl_faces(disc_body, hd / 2.0, False):
            bad.append("%s: no axial cylindrical face at R %.3f mm" % (name, hd / 2.0))

    # ---- the mount tube ----------------------------------------------------------------
    tube_occ, has_bodies = _get_or_create_component(root, "MotorMountTube")
    if not has_bodies:
        _inject(tube_occ.component,
                [("motor mount tube",
                  _annulus(tbm, TUBE_OR_MM, TUBE_IR_MM, TUBE_Z0_MM, TUBE_Z1_MM))])
        print("MotorMountTube: built, Z %.4f -> %.4f mm" % (TUBE_Z0_MM, TUBE_Z1_MM))
    else:
        print("MotorMountTube: already has bodies, verifying only")
    bad += _verify_volume(tube_occ.component,
                          {"motor mount tube": TUBE_VOLUME_MM3}, VOLUME_TOLERANCE_MM3)

    # ---- the centering rings -----------------------------------------------------------
    ring_occs = []
    for spec in RINGS:
        r_occ, has_bodies = _get_or_create_component(root, spec["name"])
        ring_occs.append((spec, r_occ))
        if not has_bodies:
            z0 = spec["z0"]
            z1 = z0 + spec["t"]
            ring = _annulus(tbm, spec["ro"], spec["ri"], z0, z1)
            # Slots for the fin tabs. Built at clocking 0 with the quadrant helper's own
            # convention, then rotated -- one technique at any angle, which is the fix
            # correction 52 made when 45 degrees broke the quadrant-parity trick.
            for q in range(spec["slots"]):
                half = spec["slot_width"] / 2.0
                slot = _quadrant_box(tbm, 0, spec["slot_r_lo"], spec["ro"] + OVER_MM,
                                     -half, half, z0 - OVER_MM, z1 + OVER_MM)
                _rotate_z(tbm, slot, AFT_FIN_CLOCK_DEG + q * 90.0)
                _cut(tbm, ring, slot, "tab slot %d" % q)
            _inject(r_occ.component, [(spec["body"], ring)])
            print("%s: built, Z %.4f -> %.4f mm, %d slots"
                  % (spec["name"], z0, z1, spec["slots"]))
        else:
            print("%s: already has bodies, verifying only" % spec["name"])
        loose = (spec["body"],) if spec["slots"] else ()
        bad += _verify_volume(r_occ.component, {spec["body"]: spec["volume"]},
                              VOLUME_TOLERANCE_MM3, loose=loose,
                              loose_tol=SLOT_TOLERANCE_MM3)

    # ---- the motor envelope, so interference has something to measure against ----------
    motor_occ, has_bodies = _get_or_create_component(root, "MotorEnvelope")
    if not has_bodies:
        _inject(motor_occ.component,
                [("motor envelope", _cyl(tbm, 0.0, 0.0, MOTOR_Z0_MM, MOTOR_Z1_MM, MOTOR_R_MM))])
        print("MotorEnvelope: built, Z %.4f -> %.4f mm" % (MOTOR_Z0_MM, MOTOR_Z1_MM))
    else:
        print("MotorEnvelope: already has bodies, verifying only")
    bad += _verify_volume(motor_occ.component, {"motor envelope": MOTOR_VOLUME_MM3},
                          VOLUME_TOLERANCE_MM3)

    # ---- interference, which is where the findings actually get demonstrated -----------
    fins = []
    for q in range(N_FINS):
        fins += _bodies_named(root, "AftFin%d" % q)
    tube_body = tube_occ.component.bRepBodies.item(0)

    print("interference:")
    pairs = []
    for i, f in enumerate(fins):
        pairs.append(("MotorMountTube vs AftFin%d" % i, tube_body, f))
    for spec, r_occ in ring_occs:
        rb = r_occ.component.bRepBodies.item(0)
        for i, f in enumerate(fins):
            pairs.append(("%s vs AftFin%d" % (spec["name"], i), rb, f))
        pairs.append(("%s vs MotorMountTube" % spec["name"], rb, tube_body))
        pairs.append(("%s vs MotorEnvelope" % spec["name"], rb,
                      motor_occ.component.bRepBodies.item(0)))
    pairs.append(("BoosterForwardBulkhead vs MotorEnvelope", disc_body,
                  motor_occ.component.bRepBodies.item(0)))
    pairs.append(("BoosterForwardBulkhead vs MotorMountTube", disc_body, tube_body))
    pairs.append(("MotorMountTube vs MotorEnvelope", tube_body,
                  motor_occ.component.bRepBodies.item(0)))
    for bt in _bodies_named(root, "BoosterTube"):
        pairs.append(("MotorMountTube vs BoosterTube", tube_body, bt))
        pairs.append(("BoosterForwardBulkhead vs BoosterTube", disc_body, bt))

    if not fins:
        bad.append("no AftFin bodies found -- run make_aft_fin_cad_fusion.py first, and "
                   "note that fins built at the OLD 12.00 mm tab depth will clash with "
                   "the mount tube by design; that is the finding, not a bug")

    for (label, a, b) in pairs:
        v = _pair_interference(tbm, a, b)
        print("  %-44s %10.4f mm3" % (label, v))
        if v > 1e-4:
            bad.append("%s: %.4f mm3" % (label, v))

    if bad:
        raise ValueError("VERIFY FAILED: " + "; ".join(bad))
    print("  OK -- motor mount built, every body within tolerance, zero interference")
